/*
 * Links extra `failed-test` issues to the fix PR that resolves them, for the fixer/verifier.
 *
 * One root cause fans out into many `failed-test` issues (one per failing test title), so a
 * single fix PR routinely resolves a dozen of them — but only the issue that requested the fix
 * ends up in its description. The rest stay open after the fix merges, and the next engineer
 * requests a fix that is already in flight. This script closes that gap from both ends: it adds
 * a `Fixes #<issue>` reference for each extra issue to the PR body (so GitHub closes them all on
 * merge, and reviewers see the real blast radius), and posts one pointer comment on each issue.
 *
 * Both halves are idempotent: the PR body block is delimited by HTML markers and rewritten in
 * place, and each issue notice carries a per-PR marker so a re-run never comments twice.
 * Everything is best-effort — a failure to link must never fail the calling workflow.
 */

const OWNER = 'elastic';
const REPO = 'kibana';
const FAILED_TEST_LABEL = 'failed-test';

// The block this script owns in the PR body. Rewritten in place on later runs.
const BLOCK_START = '<!-- flaky-fix-linked-issues:start -->';
const BLOCK_END = '<!-- flaky-fix-linked-issues:end -->';
const BLOCK_HEADING = '### Other failing-test issues this fix resolves';
const BLOCK_INTRO =
  'Traced to the same root cause as this fix, so they close with this PR. Remove a line that does not belong.';
const BULLET_PATTERN = /^- Fixes #(\d+)(?: — (.*))?$/;

// A fix plausibly covers a handful of issues; a list past this is a mislink, not a win.
const MAX_LINKED_ISSUES = 25;

// Where the block goes when it isn't in the body yet: above the fixer's trailing NOTE and the
// gh-aw footer, so it reads as part of the description instead of trailing the machine metadata.
const FOOTER_ANCHORS = ['\n> [!NOTE]', '\n> Generated by [', '\n<!-- gh-aw-'];

const CLOSING_KEYWORD = String.raw`(?:close[sd]?|fix(?:e[sd])?|resolve[sd]?)`;
// `#123`, `elastic/kibana#123`, and the full issue URL — every form GitHub itself honors.
const ISSUE_REF = String.raw`(?:${OWNER}/${REPO})?#(\d+)|https?://github\.com/${OWNER}/${REPO}/issues/(\d+)`;
const CLOSING_REF_PATTERN = new RegExp(`${CLOSING_KEYWORD}\\s+(?:${ISSUE_REF})`, 'gi');

/** Issue numbers a PR body closes on merge, from every closing-reference form GitHub honors. */
const linkedIssuesFromBody = (body) => [
  ...new Set(
    [...(body || '').matchAll(CLOSING_REF_PATTERN)].map((match) => Number(match[1] ?? match[2]))
  ),
];

/** Issue numbers from an agent-supplied list, e.g. `#285479, 285603 285607`. */
const parseIssueList = (value) => [
  ...new Set(
    String(value || '')
      .split(/[^0-9]+/)
      .filter(Boolean)
      .map(Number)
  ),
];

const noticeMarker = (prNumber) => `<!-- flaky-fix-linked-to-pr:${prNumber} -->`;

const between = (body, start, end) => {
  const from = body.indexOf(start);
  const to = body.indexOf(end);
  return from === -1 || to <= from ? null : body.slice(from + start.length, to);
};

// Entries already listed in the block, so a re-run keeps them instead of dropping them.
const entriesFromBlock = (body) =>
  (between(body || '', BLOCK_START, BLOCK_END) ?? '')
    .split('\n')
    .map((line) => line.trim().match(BULLET_PATTERN))
    .filter(Boolean)
    .map((match) => ({ number: Number(match[1]), title: match[2] || '' }));

const renderBlock = (entries) =>
  [
    BLOCK_START,
    '',
    BLOCK_HEADING,
    '',
    BLOCK_INTRO,
    '',
    ...entries.map(({ number, title }) => `- Fixes #${number}${title ? ` — ${title}` : ''}`),
    '',
    BLOCK_END,
  ].join('\n');

/** PR body with the linked-issues block rewritten in place, or inserted above the footer. */
const bodyWithBlock = (body, entries) => {
  const block = renderBlock(entries);
  const current = body || '';
  const start = current.indexOf(BLOCK_START);
  const end = current.indexOf(BLOCK_END);
  if (start !== -1 && end > start) {
    return `${current.slice(0, start)}${block}${current.slice(end + BLOCK_END.length)}`;
  }
  const anchor = FOOTER_ANCHORS.map((marker) => current.indexOf(marker))
    .filter((index) => index !== -1)
    .sort((a, b) => a - b)[0];
  const head = (anchor === undefined ? current : current.slice(0, anchor)).replace(/\s+$/, '');
  const tail = anchor === undefined ? '\n' : `\n${current.slice(anchor).replace(/^\n/, '')}`;
  return `${head}\n\n${block}\n${tail}`;
};

const noticeBody = ({ prNumber, prTitle, merged }) =>
  [
    '### 🔗 Covered by an existing fix',
    '',
    merged
      ? `#${prNumber} (\`${prTitle}\`) fixed the same root cause and has already merged, so this issue should stop failing — close it once CI confirms.`
      : `#${prNumber} (\`${prTitle}\`) fixes the same root cause, so this issue is now listed in that PR's description and closes when it merges.`,
    '',
    noticeMarker(prNumber),
  ].join('\n');

// Only a `failed-test` issue is ever a legitimate target: linking anything else would close an
// unrelated issue on merge, which is far worse than leaving one flake untracked.
const eligibilityOf = (issue) => {
  if (issue.pull_request) return 'it is a pull request, not an issue';
  if (!(issue.labels ?? []).some((label) => (label.name ?? label) === FAILED_TEST_LABEL)) {
    return `it is not labeled \`${FAILED_TEST_LABEL}\``;
  }
  if (issue.state !== 'open') return 'it is already closed';
  return null;
};

/**
 * Add a `Fixes #<issue>` reference for each of `issueNumbers` to PR `prNumber`'s description and
 * (unless `notifyIssues` is false) post one pointer comment per issue. Returns
 * `{ added, notified, skipped }`. Best-effort: per-issue problems are warnings, not throws.
 */
const linkIssuesToFixPr = async ({
  github,
  core,
  prNumber,
  issueNumbers,
  notifyIssues = true,
  owner = OWNER,
  repo = REPO,
}) => {
  const info = (message) => (core?.info ?? console.log)(message);
  const warn = (message) => (core?.warning ?? console.warn)(message);
  const skipped = [];

  const { data: pr } = await github.rest.pulls.get({ owner, repo, pull_number: prNumber });
  const alreadyLinked = new Set(linkedIssuesFromBody(pr.body));
  const requested = [...new Set((issueNumbers ?? []).map(Number))].filter(
    (number) => Number.isInteger(number) && number > 0 && number !== prNumber
  );

  const eligible = [];
  for (const number of requested) {
    if (eligible.length >= MAX_LINKED_ISSUES) {
      skipped.push({ number, reason: `the ${MAX_LINKED_ISSUES}-issue cap was reached` });
      continue;
    }
    try {
      const { data: issue } = await github.rest.issues.get({ owner, repo, issue_number: number });
      const reason = eligibilityOf(issue);
      if (reason) {
        skipped.push({ number, reason });
        continue;
      }
      eligible.push({ number, title: issue.title });
    } catch (err) {
      skipped.push({ number, reason: `it could not be read (${err.status || ''} ${err.message})` });
    }
  }
  for (const { number, reason } of skipped) {
    warn(`Not linking #${number} to #${prNumber}: ${reason}.`);
  }

  const added = eligible.filter(({ number }) => !alreadyLinked.has(number));
  const merged = Boolean(pr.merged);
  if (added.length === 0) {
    info(`No new closing references to add to #${prNumber}.`);
  } else if (pr.state !== 'open') {
    // A closed or merged PR can no longer close anything through its body; the issue notice
    // below is the only thing left to do.
    warn(
      `#${prNumber} is ${
        merged ? 'merged' : 'closed'
      }, so its description can no longer close ${added
        .map(({ number }) => `#${number}`)
        .join(', ')}; leaving it unchanged.`
    );
  } else {
    const entries = [...entriesFromBlock(pr.body), ...added].reduce(
      (unique, entry) =>
        unique.some((seen) => seen.number === entry.number) ? unique : [...unique, entry],
      []
    );
    try {
      await github.rest.pulls.update({
        owner,
        repo,
        pull_number: prNumber,
        body: bodyWithBlock(pr.body, entries),
      });
      info(`Linked ${added.map(({ number }) => `#${number}`).join(', ')} to #${prNumber}.`);
    } catch (err) {
      warn(`Could not update #${prNumber}'s description: ${err.status || ''} ${err.message}`);
    }
  }

  const notified = [];
  if (notifyIssues) {
    for (const { number } of eligible) {
      try {
        const comments = await github.paginate(github.rest.issues.listComments, {
          owner,
          repo,
          issue_number: number,
          per_page: 100,
        });
        if (comments.some((comment) => (comment.body || '').includes(noticeMarker(prNumber)))) {
          continue;
        }
        await github.rest.issues.createComment({
          owner,
          repo,
          issue_number: number,
          body: noticeBody({ prNumber, prTitle: pr.title, merged }),
        });
        notified.push(number);
      } catch (err) {
        warn(`Could not comment on #${number}: ${err.status || ''} ${err.message}`);
      }
    }
    if (notified.length > 0) {
      info(`Pointed ${notified.map((number) => `#${number}`).join(', ')} at #${prNumber}.`);
    }
  }

  return { added: added.map(({ number }) => number), notified, skipped };
};

module.exports = {
  linkIssuesToFixPr,
  linkedIssuesFromBody,
  parseIssueList,
  bodyWithBlock,
  entriesFromBlock,
  MAX_LINKED_ISSUES,
};
